import{c as e,S as t,j as o,m as r}from"./chunks/framework.i4cfd1Ha.js";const h=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"support/privacy-policy.md","filePath":"support/privacy-policy.md"}'),i={name:"support/privacy-policy.md"};function s(n,a,l,c,u,d){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><div class="info custom-block github-alert"><p class="custom-block-title">INFO</p><p><em><strong>Last Updated:</strong> 06 May 2026</em></p></div><p>This Privacy Policy describes how the <strong>Material Home Assistant Development Team</strong> (&quot;we&quot;, &quot;our&quot;), based in Italy, collects, uses, and protects your personal information when you use our service, website, and Home Assistant integrations.</p><h2 id="_1-data-controller" tabindex="-1">1. Data Controller <a class="header-anchor" href="#_1-data-controller" aria-label="Permalink to &quot;1. Data Controller&quot;">​</a></h2><p>The data controller is the development team of Material Home Assistant, located in Italy. You can reach us for any privacy-related inquiries at <code>support@materialhomeassistant.com</code>.</p><h2 id="_2-information-collected" tabindex="-1">2. Information Collected <a class="header-anchor" href="#_2-information-collected" aria-label="Permalink to &quot;2. Information Collected&quot;">​</a></h2><p>We follow a &quot;data minimization&quot; principle, collecting only what is strictly necessary to manage your license:</p><ul><li><strong>License &amp; Account Data:</strong> Email Address, Secret Key, and License Token. These are used to verify your subscription and link it to your instance.</li><li><strong>No Technical Tracking:</strong> We <strong>do not</strong> log your IP address. Our website does not use cookies for tracking, profiling, or analytics. Any cookies required for payment processing are managed exclusively by Stripe on their own domain.</li></ul><h2 id="_3-what-we-do-not-collect-local-privacy" tabindex="-1">3. What We DO NOT Collect (Local Privacy) <a class="header-anchor" href="#_3-what-we-do-not-collect-local-privacy" aria-label="Permalink to &quot;3. What We DO NOT Collect (Local Privacy)&quot;">​</a></h2><p>Material Home Assistant is designed to respect your home&#39;s privacy. We <strong>do not</strong> access, collect, or store:</p><ul><li>Data from your sensors, cameras, or smart devices.</li><li>Floor plans, names of rooms, or geographical location of your home.</li><li>Your daily habits, automation logs, or usage history.</li></ul><p>All your smart home telemetry remains strictly local to your Home Assistant instance and is never transmitted to our servers.</p><h2 id="_4-purposes-and-legal-basis" tabindex="-1">4. Purposes and Legal Basis <a class="header-anchor" href="#_4-purposes-and-legal-basis" aria-label="Permalink to &quot;4. Purposes and Legal Basis&quot;">​</a></h2><p>We process your data based on the following legal grounds:</p><ul><li><strong>Performance of a Contract:</strong> To provide the Service, manage your account, and validate your &quot;Premium&quot; or &quot;Pro&quot; license.</li><li><strong>Legal Obligations:</strong> To comply with tax regulations or requests from judicial authorities.</li></ul><h2 id="_5-payment-security-and-stripe" tabindex="-1">5. Payment Security and Stripe <a class="header-anchor" href="#_5-payment-security-and-stripe" aria-label="Permalink to &quot;5. Payment Security and Stripe&quot;">​</a></h2><p>We rely on <strong>Stripe, Inc.</strong> for financial transactions.</p><ul><li><strong>Direct Redirect:</strong> Payments are handled via a secure redirect to Stripe&#39;s platform.</li><li><strong>No Sensitive Data Storage:</strong> Material Home Assistant <strong>never</strong> sees or stores your credit card numbers, CVC codes, or expiration dates.</li><li>For more details, please consult <a href="https://stripe.com/privacy" target="_blank" rel="noreferrer">Stripe&#39;s Privacy Policy</a>.</li></ul><h2 id="_6-data-retention-and-security" tabindex="-1">6. Data Retention and Security <a class="header-anchor" href="#_6-data-retention-and-security" aria-label="Permalink to &quot;6. Data Retention and Security&quot;">​</a></h2><ul><li><strong>Retention:</strong> Your license data is kept as long as your account is active or as required by law for tax purposes.</li><li><strong>Security:</strong> We adopt industry-standard technical measures to protect your email and license tokens from unauthorized access.</li></ul><h2 id="_7-third-party-data-sharing" tabindex="-1">7. Third-Party Data Sharing <a class="header-anchor" href="#_7-third-party-data-sharing" aria-label="Permalink to &quot;7. Third-Party Data Sharing&quot;">​</a></h2><p>We do not sell, trade, or share your personal information with third parties for commercial or marketing purposes. Data is only shared with Stripe to process payments or if required by Italian/EU law.</p><h2 id="_8-your-rights-gdpr" tabindex="-1">8. Your Rights (GDPR) <a class="header-anchor" href="#_8-your-rights-gdpr" aria-label="Permalink to &quot;8. Your Rights (GDPR)&quot;">​</a></h2><p>Under the GDPR, you have the right to:</p><ul><li>Access, rectify, or request the erasure of your personal data.</li><li>Object to or restrict the processing of your data.</li><li>Request data portability.</li></ul><p>To exercise these rights, please contact us via email.</p><h2 id="_9-changes-to-this-policy" tabindex="-1">9. Changes to this Policy <a class="header-anchor" href="#_9-changes-to-this-policy" aria-label="Permalink to &quot;9. Changes to this Policy&quot;">​</a></h2><p>We may update this policy to reflect changes in our service or legal requirements. Users will be notified of significant changes through our website or via email.</p><h2 id="_10-contacts" tabindex="-1">10. Contacts <a class="header-anchor" href="#_10-contacts" aria-label="Permalink to &quot;10. Contacts&quot;">​</a></h2><p>For questions regarding your privacy:</p><div class="info custom-block github-alert"><p class="custom-block-title">INFO</p><p></p><ul><li><strong>Email:</strong> <a href="mailto:support@materialhomeassistant.com" target="_blank" rel="noreferrer">support@materialhomeassistant.com</a></li><li><strong>Website:</strong> <a href="https://www.materialhomeassistant.com" target="_blank" rel="noreferrer">https://www.materialhomeassistant.com</a></li></ul></div>',31)])])}const m=e(i,[["render",s]]);export{h as __pageData,m as default};
